import {verifiedFetchJSON} from '@github-ui/verified-fetch'

interface CreateOrUpdateCustomRoleRequest {
  path: string
  name: string
  description: string
  base_role?: string
  fgps: string[]
  roleId?: number
}

interface CreateOrUpdateCustomRoleSuccessResponse {
  success: true
  message: string
  redirect_url: string
}

interface CreateOrUpdateCustomRoleCustomRoleErrorResponse {
  success: false
  message: string
  field_errors?: Record<string, string>
}

type CreateOrUpdateCustomRoleResponse =
  | CreateOrUpdateCustomRoleSuccessResponse
  | CreateOrUpdateCustomRoleCustomRoleErrorResponse

export const createOrUpdateCustomRole = async ({
  path,
  name,
  description,
  base_role,
  fgps,
  roleId,
}: CreateOrUpdateCustomRoleRequest): Promise<CreateOrUpdateCustomRoleResponse> => {
  const role = {name, description, base_role, fgps}
  const method = roleId ? 'PUT' : 'POST'
  const url = roleId ? `${path}/${roleId}/update` : path
  const init = {
    method,
    body: role,
  }
  const response = await verifiedFetchJSON(url, init)

  if (!response.ok) {
    // Try to get the error message from the response body
    let errorData
    try {
      errorData = await response.json()
    } catch {
      // If we can't parse JSON, use the status text
      throw new Error(response.statusText)
    }

    // Throw an error with the server's message
    const error = new Error(errorData.message || response.statusText)
    // Attach the full error data for more detailed error handling
    Object.assign(error, {data: errorData})
    throw error
  }

  return await response.json()
}
