import {mainQuery} from '@github-ui/react-core/future/main-query'
import {customRolesAppBuilder} from '../config/app-builder'
import type {CustomRolePayload} from '../types'

export const customRepoRolesRoute = customRolesAppBuilder.createQueryRouteConfig('customRepoRolesRoute', {
  path: '/organizations/:slug/settings/roles/:action',
  queries: [mainQuery<CustomRolePayload>()],
})

export const customRepoRolesEditRoute = customRolesAppBuilder.createQueryRouteConfig('customRepoRolesEditRoute', {
  path: '/organizations/:slug/settings/roles/:role_id/:action',
  queries: [mainQuery<CustomRolePayload>()],
})
